Translate("esMX", "ranger-lord-hawkspear", {
	title = "Señor de los forestales Hawkspear",
	subtitle = "Señor de los forestales de Quel'Lithien",
	found = "Refugio Quel'Lithien",
	hint = [=[Busque al señor de los forestales élfico que guarda el refugio de la frontera norte.]=],
	allegiance = "Quel'Thalas",
	aliases = { "Hawkspear" },
	sections = {
		{
			title = "Resumen",
			text = [=[El señor de los forestales Hawkspear manda a los altos elfos del {link:quel-lithien-lodge}Refugio Quel'Lithien{/link}, en la frontera norte de las Tierras de la Peste. Sus forestales, leñadores y batidores defienden el camino a {link:quel-thalas}Quel'Thalas{/link} contra la {link:scourge}Plaga{/link}. El refugio guarda el Registro de Quel'Thalas, la crónica de la vida mortal de {link:nathanos-blightcaller}Nathanos Marris{/link}, que una vez fue señor de los forestales de la misma orden. Blightcaller quiere el registro, y sus siervos vienen a por él sin piedad.]=],
		},
	},
	mentions = {
		{ text = "El encargo del señor de los forestales" },
	},
	bonds = {
		{ id = "nathanos-blightcaller", name = "Nathanos Blightcaller", note = "antaño de su orden, ahora su enemigo" },
	},
})

Translate("esMX", "aurora-skycaller", {
	title = "Aurora Skycaller",
	subtitle = "Guardiana de la memoria élfica",
	found = "Cerca de la Torre del Paso Norte",
	hint = [=[Busque a la elfa que vive cerca de la Torre del Paso Norte y se lamenta por el pasado.]=],
	allegiance = "Quel'Thalas",
	aliases = { "Aurora" },
	sections = {
		{
			title = "Resumen",
			text = [=[Aurora Skycaller es una alta elfa que vive cerca de la {link:northpass-tower}Torre del Paso Norte{/link}. No le gusta hablar de la historia de su pueblo, pues le duele que los errores de sus antepasados nunca puedan deshacerse. Sin embargo, cuando un {link:dwarves}enano{/link} de la {link:explorers-league}Liga de Expedicionarios{/link} le envió los fragmentos de una reliquia rota del {link:lake-kel-theril}Lago Kel'Theril{/link}, en {link:winterspring}Cuna del Invierno{/link}, ella la reconoció como el {link:crystal-of-zin-malor}Cristal de Zin-Malor{/link}, capaz de contener y dominar grandes fuerzas arcanas. Con los escritos sagrados de los {red:highborne}Altonato{/red} y los componentes adecuados, lo recompuso, para que pudiera mostrarse a los espíritus malditos que lo habían robado hace mucho tiempo.]=],
		},
	},
	mentions = {
		{
			text = [=[Espíritus atormentados de {link:lake-kel-theril}Kel'Theril{/link}]=],
		},
		{ text = "Fragmentos del pasado" },
		{ text = "Fragmentos del pasado" },
		{ text = "Atormentados por el pasado" },
	},
})

Translate("esMX", "zaeldarr-the-outcast", {
	title = "Zaeldarr el Proscrito",
	subtitle = "Jefe de los ladrones trols muertos",
	found = "La Subgranja",
	hint = [=[Enfréntese al trol muerto que dirige a los ladrones de cuerpos de La Subgranja.]=],
	allegiance = "Plaga",
	aliases = { "Zaeldarr" },
	sections = {
		{
			title = "Resumen",
			text = [=[Zaeldarr el Proscrito es un gran trol muerto que dirige una banda de Mossflayer no-muertos desde {link:the-undercroft}La Subgranja{/link}. De noche, sus ladrones cruzan las Tierras de la Peste hasta la fosa bajo la {link:light-s-hope-chapel}Esperanza de la Luz{/link} y roban los cuerpos de los muertos del {link:alba-fairmoon}Alba{/link}. Qué hace con ellos, nadie en la Esperanza de la Luz desea adivinarlo. El vigilante {link:caretaker-alen}Alen{/link} lo quiere destruido.]=],
		},
	},
	mentions = {
		{ text = "Zaeldarr el Proscrito" },
	},
	bonds = {
		{ id = "caretaker-alen", name = "Vigilante Alen", note = "lo quiere destruido" },
	},
})

Translate("esMX", "infiltrator-hameya", {
	title = "Infiltrado Hameya",
	subtitle = "El Mossflayer infectado",
	found = "Cerca de Zul'Mashar",
	hint = [=[Encuentre al trol que suplicó la muerte antes de que la peste le arrebatara la voluntad.]=],
	allegiance = "Plaga",
	aliases = { "Hameya" },
	sections = {
		{
			title = "Resumen",
			text = [=[Hameya era un trol Mossflayer. En el camino a {link:zul-mashar}Zul'Mashar{/link}, él y sus compañeros comieron carne en mal estado, y los cambió. Hameya sintió en su mente las palabras de un exánime, que lo empujaban a volver a casa e infectar a su pueblo. Antes de que su voluntad lo abandonara, escribió un pergamino en el que suplicaba a quien lo encontrara que lo matara. Había enterrado un cofre junto a un carro detrás de {link:the-undercroft}La Subgranja{/link}, y guardaba su única llave. Ahora la {link:scourge}Plaga{/link} lo llama infiltrado, y camina hacia su propio pueblo.]=],
		},
	},
	mentions = {
		{ text = "La súplica de Hameya" },
	},
})

Translate("esMX", "duskwing", {
	title = "Duskwing",
	subtitle = "El murciélago demoníaco albino",
	found = "Los campos al norte de la Hacienda de Marris",
	hint = [=[Cace al murciélago blanco que ronda las tierras al norte de la Hacienda de Marris.]=],
	allegiance = "Ninguna",
	sections = {
		{
			title = "Resumen",
			text = [=[Duskwing es un enorme murciélago de la peste albino que recorre los campos al norte de la {link:the-marris-stead}Hacienda de Marris{/link}. {link:nathanos-blightcaller}Nathanos Blightcaller{/link} lo odia por encima de todas las alimañas de las Tierras de la Peste, y ofrece una recompensa por su pelaje blanco. Blightcaller no dice qué hizo el murciélago para ganarse su odio. Solo advierte que nadie debería cazarlo solo.]=],
		},
	},
	mentions = {
		{ text = "Duskwing, cuánto te odio..." },
	},
	bonds = {
		{ id = "nathanos-blightcaller", name = "Nathanos Blightcaller", note = "lo odia" },
	},
})

Translate("esMX", "borelgore", {
	title = "Borelgore",
	subtitle = "El Corpulento",
	found = "Los yermos del norte, al oeste de Vallenorte",
	hint = "Cace a la gran bestia larva de los yermos del norte.",
	allegiance = "Ninguna",
	aliases = { "El Corpulento" },
	sections = {
		{
			title = "Resumen",
			text = [=[Borelgore es una bestia larva de tamaño monstruoso que recorre los yermos del norte de las Tierras de la Peste, más allá de la {link:light-s-hope-chapel}Esperanza de la Luz{/link} y al oeste de {link:northdale}Vallenorte{/link}. Cuanto más come, más crece. {link:nathanos-blightcaller}Nathanos Blightcaller{/link} dice que ha perdido regimientos enteros por su culpa, y que ha devorado a más de un cazador que vino a matarla.]=],
		},
	},
	mentions = {
		{ text = "El Corpulento" },
	},
	bonds = {
		{ id = "nathanos-blightcaller", name = "Nathanos Blightcaller", note = "perdió regimientos por su culpa" },
	},
})
